  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": 1}));
  [[last, 1, "#1f4e79"], [last, 2, "#9fb4c8"], [last, 3, "#7a7a7a"], [iFeb, 1, "#1f4e79"]].forEach(function(d){
    svg.appendChild(el("circle", {cx: xp(d[0]), cy: Y(D[d[0]][d[1]]), r: 3.5, fill: d[2], stroke: "#ffffff", "stroke-width": 1}));
  });
  var pillText = "GC 2 ANS " + D[last][1].toFixed(2).replace(".", ",") + "\u00a0%";
  var pillW = Math.ceil(pillText.length * 9 * 0.68) + 10;
  var pillH = 16;
  var lastX = xp(last), lastY = Y(D[last][1]);
