  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111", "font-family": FF}, pillText));
  svg.appendChild(el("line", {x1: lastX, x2: lastX, y1: Y(D[last][1]), y2: Y(D[last][3]), stroke: "#1f4e79", "stroke-width": 1}));
  svg.appendChild(el("text", {x: lastX - 8, y: (Y(D[last][1]) + Y(D[last][3])) / 2 + 3, "text-anchor": "end", "font-size": 8, "font-weight": 700, fill: "#1f4e79", "font-family": FF}, bp(gapNow) + "\u00a0PB AU-DESSUS DU TAUX"));
  svg.appendChild(el("text", {x: lastX - 8, y: Y(winMax5) - 6, "text-anchor": "end", "font-size": 8, fill: "#6b84a0", "font-family": FF}, "GC 5 ANS " + D[last][2].toFixed(2).replace(".", ",") + "\u00a0%"));
  svg.appendChild(el("text", {x: margin.left + 8, y: Y(D[last][3]) + 11, "text-anchor": "start", "font-size": 8, fill: "#666666", "font-family": FF}, "TAUX DIRECTEUR " + D[last][3].toFixed(2).replace(".", ",") + "\u00a0%"));
  function labelAt(x, y, s, sz, col){
