  labelAt(xp(iCut) + 4, MT + 10, "30 OCT. BAISSE À " + D[iCut][3].toFixed(2).replace(".", ",") + "\u00a0%", 7.5, "#666666");
  labelAt(xp(iFeb) + 4, MT + 10, "27 FÉVR.\u00a0: " + D[iFeb][1].toFixed(2).replace(".", ",") + "\u00a0%", 7.5, "#666666");
  labelAt(xp(iFeb) + 4, MT + 22, "2 ANS +" + bp(risePct2) + "\u00a0PB DEPUIS, TAUX DIR. INCHANGÉ", 8, "#444444");
  yt.forEach(function(v){ svg.appendChild(el("text", {x: margin.left - 6, y: Y(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa", "font-family": FF}, v.toFixed(2).replace(".", ",") + "\u00a0%")); });
  mt.forEach(function(m){ svg.appendChild(el("text", {x: XT(m[0]), y: MT + PH + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999", "font-family": FF}, mo[m[1]])); });
  svg.appendChild(el("text", {x: margin.left + PW / 2, y: MT + PH + 32, "text-anchor": "middle", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "DÉBUT DE MOIS, OCT. 25 À OCT. 26"));
  svg.appendChild(el("text", {x: margin.left, y: MT - 6, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "RENDEMENTS, TAUX DIR. (%)"));
